record.content:
 \begin{definition}\textbf{The Fourier-Stieltjes algebra of a groupoid, $G_l$}.
In ref. \cite{PALT2k3}), A.L.T. Paterson defined the \emph{Fourier-Stieltjes algebra of a groupoid}, $G_l$, as the space of coefficients $\phi = (\xi,\eta)$, where $\xi,\eta$ are $L^{\infty}$-sections for some measurable $G_l$ -Hilbert bundle $(\mu,\Re,L)$. Thus, for $x \in G_l$,
\begin{equation}
\phi(x) = L(x) \xi (s(x),\eta (r(x))).
\end{equation}

Therefore, $\phi$ belongs to $L^\infty{G_l} = L^\infty({G_l},\nu)$.
\end{definition}


\begin{thebibliography}{9}
\bibitem{RW97}
A. Ramsay and M. E. Walter, Fourier-Stieltjes algebras of locally compact groupoids,
\emph{J. Functional Anal}. \textbf{148}: 314-367 (1997).

\bibitem{PALT2k1}
A. L. T. Paterson, The Fourier algebra for locally compact groupoids., Preprint, (2001).

\bibitem{PALT2k3}
A. L. T. Paterson, The Fourier-Stieltjes and Fourier algebras for locally
compact groupoids, (2003).
\end{thebibliography}
